// The context tool must describe only tools that exist. This CLI has no local
// store, so tips about sql, search, sync or pagination would send agents to
// tools that are not registered.
func TestMCPContextDoesNotAdvertiseStoreTools(t *testing.T) {
	s := server.NewMCPServer("japan-timed-tickets", "test")
	RegisterTools(s)

	result, err := handleContext(s)(context.Background(), mcplib.CallToolRequest{})
	if err != nil {
		t.Fatalf("handleContext() error = %v", err)
	}
	var payload struct {
		QueryTips []string `json:"query_tips"`
		Resources []struct {
			Tool string `json:"tool"`
		} `json:"resources"`
	}
	if err := json.Unmarshal([]byte(mcpTextContent(t, result)), &payload); err != nil {
		t.Fatalf("context result must be valid JSON: %v", err)
	}
	for _, tip := range payload.QueryTips {
		lower := strings.ToLower(tip)
		for _, banned := range []string{"sql", "sync", "search tool", "pagination", "cursor"} {
			if strings.Contains(lower, banned) {
				t.Fatalf("query tip %q mentions %q, which this CLI does not have", tip, banned)
			}
		}
	}
	if len(payload.Resources) == 0 {
		t.Fatal("context lists no resources")
	}
	for _, r := range payload.Resources {
		if s.GetTool(r.Tool) == nil {
			t.Fatalf("context resource points at tool %q, which is not registered", r.Tool)
		}
	}
}
